# Resource ledger for PreVal jobs on EVE: wall time, CPU time, cores and RAM (peak, requested), per job name and start day.
# Input : a sacct dump made with
#   sacct -u $USER -S <date> -E now -n -P -o JobID,JobName,State,Elapsed,TotalCPU,AllocCPUS,ReqMem,MaxRSS,Start > sacct_all.psv
#   (the dump may start with login-banner lines: they are ignored)
# Usage : Rscript simulation/make_resource_ledger.R <sacct_all.psv> [outDir=simulation/ledger]
# Output: ledger_by_job_day.csv (one row per job name and start day), ledger_by_job_day.md (same as a table), ledger_simulation_tasks.csv (one row per task of the sim-* jobs).
# CREATED 2026-11-14. Only names starting with "preval" or "sim-" are PreVal; caribou jobs also carry the name preval-* (told apart by start day only).
suppressMessages(library(data.table))
a <- commandArgs(trailingOnly = TRUE); if (!length(a)) stop("usage: Rscript simulation/make_resource_ledger.R <sacct_all.psv> [outDir]")
outDir <- if (length(a) >= 2) a[2] else "simulation/ledger"; dir.create(outDir, showWarnings = FALSE, recursive = TRUE)
x <- fread(a[1], sep = "|", header = FALSE, fill = TRUE, col.names = c("JobID", "JobName", "State", "Elapsed", "TotalCPU", "AllocCPUS", "ReqMem", "MaxRSS", "Start"), colClasses = "character")
x <- x[grepl("^[0-9]+(_[0-9]+)?(\\.[a-z0-9+]+)?$", JobID)]
secs <- function(s) vapply(s, function(v) { if (is.na(v) || !nzchar(v)) return(NA_real_)
  d <- 0; if (grepl("-", v)) { d <- as.numeric(sub("-.*", "", v)); v <- sub("^[0-9]+-", "", v) }
  p <- as.numeric(strsplit(v, ":")[[1]]); h <- if (length(p) == 3) p[1] * 3600 + p[2] * 60 + p[3] else if (length(p) == 2) p[1] * 60 + p[2] else p[1]; d * 86400 + h }, numeric(1), USE.NAMES = FALSE)
gb <- function(s) vapply(s, function(v) { if (is.na(v) || !nzchar(v)) return(NA_real_); u <- sub("^[0-9.]+", "", v); n <- as.numeric(sub("[A-Za-z]+$", "", v))
  f <- switch(substr(u, 1, 1), K = 1 / 1024^2, M = 1 / 1024, G = 1, T = 1024, 1 / 1024^3); n * f }, numeric(1), USE.NAMES = FALSE)
x[, isStep := grepl("\\.", JobID)]
mem <- x[isStep & grepl("\\.batch$", JobID), .(JobID = sub("\\.batch$", "", JobID), peakGB = gb(MaxRSS))]
jobs <- x[!isStep & grepl("^(preval|sim-)", JobName)]
jobs <- merge(jobs, mem, by = "JobID", all.x = TRUE)
jobs[, `:=`(wallH = secs(Elapsed) / 3600, cpuH = secs(TotalCPU) / 3600, cores = as.integer(AllocCPUS), reqGBperCore = gb(sub("[cn]$", "", ReqMem)), day = substr(Start, 1, 10))]
jobs <- jobs[day != "Unknown" & !is.na(wallH)]
jobs[, reqGBtotal := reqGBperCore]      # EVE's sacct prints ReqMem as the job TOTAL (e.g. 12G for 4 cores x 3G; checked 2026-11-14 on 66672053), so no multiplication by cores
jobs[, array := sub("_.*", "", JobID)]
by <- jobs[, .(tasks = .N, completed = sum(State == "COMPLETED"), timeout = sum(grepl("TIMEOUT", State)), outOfMemory = sum(grepl("OUT_OF_MEMORY", State)), failedOther = sum(State %in% c("FAILED", "NODE_FAIL")), cancelled = sum(grepl("CANCELLED", State)),
               cores = paste(sort(unique(cores)), collapse = "/"), wallMin_min = round(min(wallH) * 60), wallMin_median = round(median(wallH) * 60), wallMin_max = round(max(wallH) * 60),
               cpuHours_total = round(sum(cpuH, na.rm = TRUE), 1), peakRAM_GB_median = round(median(peakGB, na.rm = TRUE), 2), peakRAM_GB_max = round(max(peakGB, na.rm = TRUE), 2),
               requestedRAM_GB = paste(sort(unique(round(reqGBtotal, 1))), collapse = "/")), by = .(job = sub("\\d+$", "", JobName), day)]
by[!is.finite(peakRAM_GB_max), `:=`(peakRAM_GB_median = NA_real_, peakRAM_GB_max = NA_real_)]
setorder(by, day, job)
fwrite(by, file.path(outDir, "ledger_by_job_day.csv"))
simT <- jobs[grepl("^sim-", JobName), .(array, task = ifelse(grepl("_", JobID), sub(".*_", "", JobID), NA), job = JobName, State, wallMin = round(wallH * 60), cpuHours = round(cpuH, 2), cores, peakRAM_GB = round(peakGB, 2), requestedRAM_GB = round(reqGBtotal, 1), start = Start)]
fwrite(simT, file.path(outDir, "ledger_simulation_tasks.csv"))
md <- c("# Resource ledger (EVE), generated by simulation/make_resource_ledger.R", "",
        sprintf("Source: %s; %d PreVal job records (names preval-* and sim-*). Wall time in minutes per task; RAM = peak resident memory of the batch step (MaxRSS); requested = what the job asked for in total.", basename(a[1]), nrow(jobs)),
        "Caribou jobs also carry the name preval-*; they are told apart by start day only.", "",
        "| day | job | tasks | ok | timeout | OOM | failed | cancelled | cores | wall min (min / median / max) | CPU-hours | peak RAM GB (median / max) | requested GB |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|")
md <- c(md, by[, sprintf("| %s | %s | %d | %d | %d | %d | %d | %d | %s | %d / %d / %d | %.1f | %s / %s | %s |", day, job, tasks, completed, timeout, outOfMemory, failedOther, cancelled, cores, wallMin_min, wallMin_median, wallMin_max,
                         cpuHours_total, ifelse(is.na(peakRAM_GB_median), "NA", formatC(peakRAM_GB_median, format = "f", digits = 2)), ifelse(is.na(peakRAM_GB_max), "NA", formatC(peakRAM_GB_max, format = "f", digits = 2)), requestedRAM_GB)])
writeLines(md, file.path(outDir, "ledger_by_job_day.md"))
cat(paste(md, collapse = "\n"), "\n")
